_theme.layout:
# --- 恋爱全息终端 v9.2 (视角修正版) ---
# 💖 增加爱心上浮粒子背景
@particles hearts 15

@text topHeader .pulse

# 弹幕监控流
@marquee bullets1 .fast
@marquee bullets2 .slow
@marquee bullets3 .mid

@spacer 10

# 观测主体与心动率 (带发光特效)
@duo charImage charName userImage userName .fadeInDown
@bar syncRate "SYNC RATE [%]" .glow

@spacer 10

# 恋爱分析矩阵（宿主状态）
@section HOST STATUS [Ⅰ] .fadeInUp.delay100
  charStatus

@grid 3 .stagger
  heartbeat:bar "HEART"
  sweetness:bar "SWEET"
  oocIndex:bar "OOC"

# 目标弱点扫描与系统建议
@section TARGET WEAKNESS SCAN [Ⅱ] .fadeInUp.delay200
  weakness

@section SYSTEM ADVICE [Ⅲ] .fadeInUp.delay200
  sysAdvice

# 任务列表
@collapse "ACTIVE TASKS [Ⅳ]" 1 .fadeInUp.delay300
@list
  task1
  task2
  task3
@endcollapse

# 脑内频段截获 (系统 vs 宿主)
@collapse "INTERCEPTED AUDIO [Ⅴ]" 2 .fadeInUp.delay400
@bubbles
  msg1:left
  msg2:right
  msg3:left
  msg4:right
  msg5:left
@endcollapse

@spacer 10

# ⚠️ 宿主真实心声直接展示
@section TRUE FEELINGS [Ⅵ] .fadeInUp.delay500
  trueVoice

@bar heRate "HE结局预测达成率 [%]" .breathe

# 动态状态标签
@tags .fadeIn.delay600
  tag1
  tag2
  tag3

_theme.customCss:
@import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&display=swap');

.xt-root {
  /* 深色磨砂透感背景 */
  --xt-bg: rgba(15, 10, 15, 0.65);
  --xt-text: #ffffff;
  --xt-text-sub: #dddddd;
  --xt-text-muted: #888888;

  /* 恋爱主题色：淡粉色 */
  --xt-accent: #ff99bb;      
  --xt-accent-bg: rgba(255, 153, 187, 0.15);
  --xt-border: rgba(255, 255, 255, 0.2);
  --xt-glow-color: rgba(255, 153, 187, 0.5); /* 为 .glow 动画设置发光色 */

  --xt-radius: 4px; 
  --xt-font: 'Share Tech Mono', monospace, sans-serif;

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  border: 1px solid var(--xt-border);
  box-shadow: inset 0 0 30px rgba(0,0,0,0.3), 0 8px 32px rgba(0,0,0,0.4);
  letter-spacing: 1px;
}

/* 顶部文字 */
.xt-text-topHeader {
  color: var(--xt-accent);
  font-size: 10px;
  letter-spacing: 3px;
  border-bottom: 1px dashed var(--xt-border);
  padding-bottom: 5px;
}
.xt-text-topHeader::before { content: "♥ "; animation: pulse 1s infinite; }

/* 弹幕区 */
.xt-marquee { mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent); margin-bottom: 2px; }
.xt-marquee-inner { font-size: 11px; color: rgba(255,255,255,0.6); white-space: pre !important; }
.xt-marquee:nth-of-type(2) .xt-marquee-inner { color: var(--xt-accent); text-shadow: 0 0 5px rgba(255,153,187,0.3); } 
.xt-marquee.fast .xt-marquee-inner { animation-duration: 6s !important; }
.xt-marquee.mid .xt-marquee-inner { animation-duration: 9s !important; }
.xt-marquee.slow .xt-marquee-inner { animation-duration: 12s !important; }

/* 头像：全彩 + 粉色边框 */
.xt-duo-avatar {
  border-radius: 50% !important;
  border: 2px solid var(--xt-accent);
  box-shadow: 0 0 10px rgba(255,153,187,0.3);
}
.xt-duo-heart { color: var(--xt-accent); font-size: 16px; }

/* 暴力清除默认左侧粗边框和背景 */
.xt-section-body, .xt-collapse-body, .xt-list {
  border-left: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding-left: 0 !important;
}

/* 重新定义标题块样式 */
.xt-section-title, .xt-collapse-header {
  border-left: 2px solid var(--xt-accent) !important;
  border-radius: 0 !important;
  padding-left: 8px !important;
  font-size: 12px;
  color: #eeeeee;
  background: linear-gradient(90deg, rgba(255,153,187,0.1), transparent) !important;
  margin-top: 5px;
  margin-bottom: 5px;
}

/* 正文与数据网格条 */
.xt-section-body { color: #dddddd; font-size: 13px; }
.xt-bar-track { background: rgba(255,255,255,0.1); border-radius: 2px; height: 6px; }
.xt-bar-fill { background: #ffffff; border-radius: 2px; }
.xt-grid-bar:nth-child(3) .xt-bar-fill { background: var(--xt-accent); box-shadow: 0 0 8px var(--xt-accent); }

/* 列表与气泡 */
.xt-list-item { border-bottom: 1px solid rgba(255,255,255,0.05); color: #cccccc; font-size: 12px; }
.xt-list-check { display: none; }
.xt-list-item::before { content: "♥ "; color: var(--xt-accent); font-size: 10px; }

.xt-bubble-body {
  border-radius: 8px !important;
  font-size: 12px;
  background: rgba(255,255,255,0.05) !important;
  border: 1px solid rgba(255,255,255,0.1) !important;
  color: #cccccc !important;
}
.xt-bubble-left .xt-bubble-body { border-left: 2px solid #888 !important; }
.xt-bubble-right .xt-bubble-body { border-right: 2px solid var(--xt-accent) !important; color: #ffffff !important; }

/* 真实心声区块发光高亮 */
.xt-section:last-of-type .xt-section-title {
  color: var(--xt-accent) !important;
  border-left: 3px solid #ff4d88 !important;
  background: linear-gradient(90deg, rgba(255,77,136,0.2), transparent) !important;
}
.xt-section:last-of-type .xt-section-body {
  font-style: italic;
  border: 1px dashed rgba(255, 153, 187, 0.4);
  padding: 12px;
  background: rgba(255, 153, 187, 0.08);
  border-radius: 6px;
  color: #ffffff;
  text-shadow: 0 0 5px rgba(255, 153, 187, 0.3);
  margin-bottom: 10px;
}

/* 底部随机动态标签 */
.xt-tag { 
  background: rgba(255, 153, 187, 0.15); 
  border: 1px solid var(--xt-accent); 
  color: #ffffff; 
  font-size: 11px; 
  border-radius: 4px;
}

/* 爱心粒子特效微调：让爱心呈现半透明粉色，更梦幻 */
.xt-particles-hearts .xt-particle {
  color: rgba(255, 153, 187, 0.6) !important;
  text-shadow: 0 0 5px rgba(255, 153, 187, 0.8);
}
/* 隐藏双头像下的名字，只保留头像和爱心 */
.xt-duo-name {
  display: none !important;
}

