_theme.customCss:
/* 全局容器：监控档案风格 */
.xt-root {
  --xt-bg: #161617; 
  --xt-text: #e0e0e0; 
  --xt-accent: #ff3e3e; 
  --xt-border: transparent;
  --xt-font: "ZCOOL QingKe HuangYou", cursive;

  background: var(--xt-bg);
  clip-path: polygon(2% 1%, 98% 3%, 100% 97%, 95% 100%, 5% 98%, 0% 95%);
  padding: 20px 20px 50px 20px;
  box-shadow: 0 10px 40px rgba(0,0,0,0.8);
  position: relative;
  overflow: hidden !important;
}

/* 全屏扫描线动效 */
.xt-root::before {
  content: "";
  position: absolute;
  top: -100%; left: 0;
  width: 100%; height: 100px;
  background: linear-gradient(to bottom, transparent, rgba(255, 62, 62, 0.08), transparent);
  animation: scanning 4s linear infinite;
  z-index: 5;
  pointer-events: none;
}

@keyframes scanning {
  0% { top: -20%; }
  100% { top: 120%; }
}

/* 装饰：黑色胶带（移到内容区顶部） */
.xt-content::before {
  content: "";
  position: absolute;
  top: -30px; left: 40%;
  width: 80px; height: 30px;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(2px);
  transform: rotate(-15deg);
  z-index: 100;
}

/* 装饰：OBSERVED印章 */
.xt-root::after {
  content: "OBSERVED";
  position: absolute;
  bottom: 25px; right: 15px;
  width: 65px; height: 65px;
  border: 2px double var(--xt-accent);
  border-radius: 50%;
  color: var(--xt-accent);
  font-size: 11px;
  display: flex; align-items: center; justify-content: center;
  opacity: 0.5;
  transform: rotate(25deg);
  pointer-events: none;
  filter: drop-shadow(0 0 5px rgba(255,62,62,0.5));
}

/* 粒子干扰 */
.xt-particles-rain .xt-particle {
  background: var(--xt-accent) !important;
  width: 1px !important;
  opacity: 0.2;
}

/* 暴力重置样式：杀掉所有多余边框和背景 */
.xt-section, .xt-text, .xt-section-body, .xt-collapse-body .xt-section {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 5px 0 !important;
}

/* 红色侧边线 */
.xt-section {
  border-left: 2px solid var(--xt-accent) !important;
  padding-left: 12px !important;
  margin-bottom: 15px !important;
}

.xt-section-title {
  color: var(--xt-accent);
  font-size: 11px;
  margin-bottom: 4px;
}

/* 【核心修复】文字扫光动效：不再使用透明色，确保文字可见 */
.xt-quote {
  background: #202022 !important;
  color: #ffffff !important; /* 强制白色，保证可见 */
  clip-path: polygon(1% 2%, 99% 0%, 96% 98%, 4% 100%);
  padding: 18px !important;
  border: 1px solid rgba(255,255,255,0.05) !important;
  position: relative;
  overflow: hidden;
}

.xt-anim-shimmer {
  /* 使用文本阴影和背景渐变来实现扫光，而不隐藏文字本身 */
  background: linear-gradient(110deg, #fff 45%, var(--xt-accent) 50%, #fff 55%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  animation: paper-shimmer 3s infinite linear;
  /* 如果引擎不支持 background-clip，则 fallback 到普通白色 */
  text-shadow: 0 0 2px rgba(255, 62, 62, 0.2);
}

@keyframes paper-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* 内容滑动修复 */
.xt-content {
  max-height: 500px !important;
  overflow-y: auto !important;
  padding-right: 10px;
}
.xt-content::-webkit-scrollbar-thumb {
  background: var(--xt-accent);
}

/* 折叠面板内部滑动 */
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body {
  max-height: 250px !important;
  overflow-y: auto !important;
  border-top: 1px dashed #333;
  padding-top: 10px;
}

.xt-collapse-header {
  color: var(--xt-accent);
  font-weight: bold;
}

.xt-badge {
  background: #2a2a2c;
  color: #bbb;
  border: 1px solid #3d3d3f;
}

