  --xt-font: -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;

  background-image: url("https://imgbed.heliar.top/file/1776214157995_IMG_20260415_084906.jpg");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  position: relative;
  max-height: 75vh;
  overflow-y: auto !important;
  padding: 0;
}
.xt-root::before {
  content: "";
  position: absolute;
  top:0;left:0;right:0;bottom:0;
  background: rgba(0,0,0,0.15);
  z-index: 0;
  pointer-events: none;
}
.xt-content { position: relative; z-index: 1; }
.xt-root::-webkit-scrollbar {width:4px;}
.xt-root::-webkit-scrollbar-thumb {background:#ff5599; border-radius:4px;}
.xt-root::-webkit-scrollbar-track {background:rgba(0,0,0,0.3);}

.xt-header {
  position: relative;
  display: flex;
  align-items: center;
  padding: 8px 14px;
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(6px);
  margin-bottom: 10px;
  z-index: 2;
}
.xt-header::after {
  content: "一顆心 可以衹有我嗎";
  margin-left: auto;
  font-size: 11px;
  color: #ff5599;
  white-space: nowrap;
}

.xt-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid #ff5599;
  margin-right: -2px;
  flex-shrink: 0;
}

.xt-name {
  font-size: 14px;
  color: #fff;
  line-height: 1.2;
  position: relative;
  margin-top: 0px;
}
.xt-name::after {
  content: "已关注";
  margin-left: 8px;
  background: #000;
  color: #ff5599;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 20px;
}

.xt-section {
  background: rgba(0,0,0,0.5);
  border-radius: 12px;
  padding: 14px;
  margin: 0 14px 10px;
  border: 1px solid var(--xt-border);
  z-index: 2;
}
.xt-section-title {
  font-size: 12px;
  color: #ff5599;
  letter-spacing: 1px;
  margin:0;
}
.xt-section-body {
  font-size: 14px;
  line-height: 1.6;
  color: #fff;
  margin-top: 6px;
}

.xt-section-3 .xt-section-body div {
  margin: 6px 0;
  padding: 4px 0;
}
.xt-section-3 .xt-section-body div:nth-child(odd) {
  color: #ccc;
  font-size: 13px;
}
.xt-section-3 .xt-section-body div:nth-child(even) {
  color: #fff;
  font-size: 14px;
  padding-left: 10px;
  border-left: 2px solid #ff5599;
  background: rgba(255,85,153,0.08);
  border-radius: 0 6px 6px 0;
  padding-bottom: 8px;
  margin-bottom: 8px;
  position: relative;
}
.xt-section-3 .xt-section-body div:nth-child(even)::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 1px;
  background: rgba(255,85,153,0.2);
}
.xt-section-3 .xt-section-body div:nth-last-child(1)::after {
  display: none;
}

.xt-grid {
  gap:10px;
  margin:0 14px 10px;
  position: relative;
  z-index:2;
}
.xt-grid-stat {
  background:rgba(0,0,0,0.5);
  border:1px solid var(--xt-border);
  border-radius:12px;
  padding:14px;
  text-align:left;
}
.xt-grid-stat-label {font-size:12px;color:#ff5599;}
.xt-grid-stat-value {font-size:14px;color:#fff;line-height:1.5}

.xt-section-4 .xt-section-body div {
  display:flex;
  align-items:center;
  gap:8px;
  margin-bottom:6px;
  color:#fff;
}
.xt-section-4 .xt-section-body div::before {
  content:"✓";
  width:16px; height:16px;
  border:1px solid #ff5599;
  border-radius:4px;
  color:#ff5599;
  font-size:12px;
  display:flex;
  align-items:center;
  justify-content:center;
  flex-shrink:0;
}

.xt-section-5 { margin-bottom:14px; }

